<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue'
import { ElInput,ElSelect,ElOption,ElButton,ElTag,ElAlert,ElPagination,ElDialog,ElCheckbox } from 'element-plus'
import { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
const props=defineProps<{api:API}>();const emit=defineEmits<{source:[id:string];open:[page:string]}>()
const query=ref(''),status=ref('active'),page=ref(1),records=ref<any>(null),selected=ref<any>(null),timeline=ref<any[]>([]),error=ref(''),loading=ref(false)
const editing=ref(false),saving=ref(false),draft=ref(''),reason=ref(''),checked=ref(false)
let timer:ReturnType<typeof setTimeout>,alive=true
const names:Record<string,string>={fact:'事实',preference:'偏好',profile:'画像',goal:'目标',procedure:'流程'}
async function load(){loading.value=true;try{records.value=await props.api.request('/studio/memories?'+new URLSearchParams({q:query.value,status:status.value,page:String(page.value)}),undefined,'GET','memory-inventory')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)loading.value=false}}
async function choose(item:any){selected.value=item;timeline.value=[];try{const result=await props.api.request('/memories/'+encodeURIComponent(item.id)+'/timeline',undefined,'GET','memory-timeline');if(alive&&selected.value?.id===item.id)timeline.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}}
function edit(){if(!selected.value)return;draft.value=selected.value.content;reason.value='';checked.value=false;editing.value=true}
async function correct(){if(!selected.value||!checked.value||!draft.value.trim()||!reason.value.trim())return;saving.value=true;const id=selected.value.id;try{const result=await props.api.request('/memories/'+encodeURIComponent(id)+'/correct',{content:draft.value.trim(),kind:selected.value.kind,importance:selected.value.importance,reason:reason.value.trim()});if(alive){editing.value=false;await load();await choose(result)}}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)saving.value=false}}
async function exportMemory(){saving.value=true;try{const text=await props.api.request<string>('/memories/export.md',undefined,'GET','memory-export','text');if(!alive)return;const link=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));link.href=url;link.download='memoria-memories.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)saving.value=false}}
watch([query,status],()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load()},300)})
onMounted(()=>void load());onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="section-title"><div><h2>长期记忆库 <span class="count-label">{{ records?.total??'—' }} 条</span></h2><p>查看记忆正文、来源和状态，原始对话由历史对话入口查看。</p></div><div class="actions"><el-button :disabled="saving||!records?.total" @click="exportMemory">导出记忆 Markdown</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><div class="inventory-filters"><el-input v-model="query" clearable placeholder="搜索记忆正文" maxlength="200"/><el-select v-model="status" aria-label="记忆状态"><el-option value="active" label="有效记忆"/><el-option value="superseded" label="被替代的历史"/><el-option value="all" label="全部状态"/></el-select></div><table v-if="records?.items.length" class="data-table"><thead><tr><th>记忆内容</th><th>类型</th><th>状态</th><th>重要度</th><th>更新记录</th></tr></thead><tbody><tr v-for="item in records.items" :key="item.id" @click="choose(item)" tabindex="0" @keydown.enter="choose(item)"><td class="memory-content-cell">{{ item.content }}</td><td>{{ names[item.kind]??item.kind }}</td><td><el-tag size="small">{{ item.status }}</el-tag></td><td>{{ item.importance }} / 5</td><td>{{ dateLabel(item.updated_at) }}</td></tr></tbody></table><div v-else-if="loading&&!records" class="empty" role="status">正在读取长期记忆…</div><div v-else class="empty"><span>◈</span><h3>{{ query?'没有匹配的记忆':'这个账号还没有有效记忆' }}</h3><p>已有对话不会自动等于已批准的长期记忆。你可以先阅读历史，核对适用来源后再进行审核。</p><el-button @click="emit('open','conversations')">从本人原话提出候选</el-button><el-button @click="emit('open','reviews')">前往候选审核</el-button><el-button @click="emit('open','pipeline')">查看为什么为空</el-button></div><el-pagination v-if="records?.total" layout="total, prev, pager, next" :total="records.total" :page-size="50" :current-page="records.page" @current-change="(p:number)=>{page=p;load()}"/></section><section v-if="selected" class="panel"><div class="section-title"><h2>记忆详情</h2><el-tag>{{ names[selected.kind]??selected.kind }}</el-tag></div><div class="source-original">{{ selected.content }}</div><dl><dt>来源</dt><dd>{{ selected.source }}</dd><dt>创建时间</dt><dd>{{ dateLabel(selected.created_at,true) }}</dd><dt>更新记录</dt><dd>{{ dateLabel(selected.updated_at,true) }}</dd><dt>强化次数</dt><dd>{{ selected.reinforcement }}</dd></dl><el-button v-if="selected.status==='active'" type="primary" @click="edit">纠正记忆并保留旧版本</el-button><el-button v-if="selected.source_ref" @click="emit('source',selected.source_ref)">核对原始来源 ↗</el-button><el-button @click="emit('open','explorer')">进入结构化记忆审核</el-button><h3>版本与来源时间线</h3><p>以下是记录与修订时间，不补作事实发生时间。来源可能位于旧版本。</p><div class="feature-table"><table v-if="timeline.length" class="data-table"><thead><tr><th>记录时间</th><th>正文</th><th>当前状态</th><th>变更原因 / 来源</th></tr></thead><tbody><tr v-for="version in timeline" :key="version.id"><td>{{ dateLabel(version.created_at,true) }}</td><td class="memory-content-cell">{{ version.content }}</td><td>{{ version.status }}</td><td>{{ version.replacement_reason||version.source }}<el-button v-if="version.source_ref" size="small" @click="emit('source',version.source_ref)">核对该版本原话</el-button></td></tr></tbody></table></div><details><summary>查看版本原始字段</summary><pre>{{ JSON.stringify(timeline,null,2) }}</pre></details></section><el-dialog v-model="editing" title="纠正长期记忆" width="min(560px,94vw)"><p>纠正会创建新版本并保留旧版本，可能调用已配置的Embedding。请保留原话支持的主体与适用条件。</p><label>修订内容<el-input v-model="draft" type="textarea" :rows="5" maxlength="4000"/></label><label>纠正原因<el-input v-model="reason" maxlength="500"/></label><el-checkbox v-model="checked">已核对来源和修订内容</el-checkbox><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :disabled="!checked||!draft.trim()||!reason.trim()" :loading="saving" @click="correct">确认创建纠正版本</el-button></template></el-dialog></template>
